template:
{%- set ns = namespace(all_commands=[]) -%}
{%- for cmds in input.commandsList.values() -%}
  {%- for cmd in cmds -%}
    {%- set ns.all_commands = ns.all_commands + [cmd] -%}
  {%- endfor -%}
{%- endfor -%}
{"template" : {
  "name": "{{templateName}}",
  "tags" : [],
  "type" : "templates",
  "_id" : "{{templateName}}",
  "os": "",
  "passRule": true,
  "ignoreWarnings": false,
  "commands": [
    {%- for cmd in ns.all_commands %}
    {
      "command": {{ cmd | tojson }},
      "passRule": true,
      "rules": [
        {
          "rule": "",
          "eval": "contains",
          "severity": "error"
        }
      ]
    }{{ "," if not loop.last }}
    {%- endfor %}
